# React Error Boundary Component

## Component Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorLog {
  message: string;
  stack?: string;
  componentStack?: string;
  timestamp: string;
  errorId: string;
}

interface Props {
  children: ReactNode;
  /** Custom fallback UI; receives error + retry handler */
  fallback?: (error: Error, retry: () => void) => ReactNode;
  /** Called after the error is logged */
  onError?: (log: ErrorLog) => void;
  /** Scope label shown in logs (e.g. "UserProfile") */
  scope?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorLog: ErrorLog | null;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

function generateErrorId(): string {
  return `ERR-${Date.now()}-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
}

function buildErrorLog(
  error: Error,
  info: ErrorInfo,
  scope: string
): ErrorLog {
  const log: ErrorLog = {
    message: `[${scope}] ${error.message}`,
    stack: error.stack,
    componentStack: info.componentStack ?? undefined,
    timestamp: new Date().toISOString(),
    errorId: generateErrorId(),
  };

  // Console output — replace with your real logging service (Sentry, Datadog…)
  console.group(`🔴 ErrorBoundary caught — ${log.errorId}`);
  console.error("Message        :", log.message);
  console.error("Timestamp      :", log.timestamp);
  console.error("JS Stack       :\n", log.stack);
  console.error("Component Stack:\n", log.componentStack);
  console.groupEnd();

  return log;
}

// ─── Error Boundary ───────────────────────────────────────────────────────────

class ErrorBoundary extends Component<Props, State> {
  static defaultProps: Partial<Props> = {
    scope: "App",
  };

  state: State = {
    hasError: false,
    error: null,
    errorLog: null,
  };

  // Triggered during render — update state so next render shows fallback
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // Triggered after render — ideal place for side-effects (logging)
  componentDidCatch(error: Error, info: ErrorInfo): void {
    const log = buildErrorLog(error, info, this.props.scope!);
    this.setState({ errorLog: log });
    this.props.onError?.(log);
  }

  private handleRetry = (): void => {
    this.setState({ hasError: false, error: null, errorLog: null });
  };

  render(): ReactNode {
    const { hasError, error, errorLog } = this.state;
    const { children, fallback } = this.props;

    if (!hasError || !error) return children;

    // Consumer-supplied fallback
    if (fallback) return fallback(error, this.handleRetry);

    // Built-in fallback UI
    return (
      <DefaultFallback
        error={error}
        errorLog={errorLog}
        onRetry={this.handleRetry}
      />
    );
  }
}

export default ErrorBoundary;

// ─── Default Fallback UI ──────────────────────────────────────────────────────

interface FallbackProps {
  error: Error;
  errorLog: ErrorLog | null;
  onRetry: () => void;
}

function DefaultFallback({ error, errorLog, onRetry }: FallbackProps) {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div style={styles.overlay} role="alert" aria-live="assertive">
      <div style={styles.card}>
        {/* Header */}
        <div style={styles.header}>
          <span style={styles.icon} aria-hidden="true">⚠️</span>
          <h2 style={styles.title}>Something went wrong</h2>
        </div>

        {/* Summary */}
        <p style={styles.message}>
          An unexpected error occurred. You can try recovering by clicking the
          button below.
        </p>

        {/* Error badge */}
        {errorLog && (
          <p style={styles.errorId}>
            Error ID:{" "}
            <code style={styles.code}>{errorLog.errorId}</code>
          </p>
        )}

        {/* Actions */}
        <div style={styles.actions}>
          <button onClick={onRetry} style={styles.retryButton}>
            🔄 Retry
          </button>
          <button
            onClick={() => setShowDetails((v) => !v)}
            style={styles.detailsButton}
            aria-expanded={showDetails}
          >
            {showDetails ? "Hide" : "Show"} Details
          </button>
        </div>

        {/* Collapsible details */}
        {showDetails && (
          <details open style={styles.details}>
            <summary style={styles.summary}>Error details</summary>
            <pre style={styles.pre}>
              <strong>Message:</strong>{"\n"}{error.message}
              {"\n\n"}
              <strong>Stack:</strong>{"\n"}{error.stack}
              {errorLog?.componentStack && (
                `\n\nComponent Stack:\n${errorLog.componentStack}`
              )}
            </pre>
          </details>
        )}
      </div>
    </div>
  );
}

// ─── Minimal inline styles (swap for CSS Modules / Tailwind as needed) ────────

const styles: Record<string, React.CSSProperties> = {
  overlay: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    backgroundColor: "#f8f9fa",
    padding: "1rem",
    fontFamily: "system-ui, sans-serif",
  },
  card: {
    background: "#ffffff",
    border: "1px solid #dee2e6",
    borderRadius: "8px",
    boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
    maxWidth: "540px",
    width: "100%",
    padding: "2rem",
  },
  header: {
    display: "flex",
    alignItems: "center",
    gap: "0.75rem",
    marginBottom: "1rem",
  },
  icon: { fontSize: "1.75rem" },
  title: { margin: 0, fontSize: "1.25rem", color: "#212529" },
  message: { color: "#495057", lineHeight: 1.6, marginBottom: "0.75rem" },
  errorId: { fontSize: "0.8rem", color: "#868e96", marginBottom: "1.25rem" },
  code: {
    background: "#f1f3f5",
    padding: "2px 6px",
    borderRadius: "4px",
    fontFamily: "monospace",
  },
  actions: { display: "flex", gap: "0.75rem", marginBottom: "1rem" },
  retryButton: {
    padding: "0.5rem 1.25rem",
    background: "#228be6",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontWeight: 600,
    fontSize: "0.9rem",
  },
  detailsButton: {
    padding: "0.5rem 1.25rem",
    background: "transparent",
    color: "#495057",
    border: "1px solid #ced4da",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "0.9rem",
  },
  details: {
    marginTop: "1rem",
    borderTop: "1px solid #e9ecef",
    paddingTop: "1rem",
  },
  summary: { cursor: "pointer", color: "#495057", fontWeight: 600 },
  pre: {
    marginTop: "0.75rem",
    background: "#f8f9fa",
    padding: "1rem",
    borderRadius: "4px",
    fontSize: "0.78rem",
    overflow: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
    color: "#c92a2a",
  },
};
```

